function initMagneticButtons(){var t=document.querySelectorAll(".magnetic-btn");if(t.length&&!window.matchMedia("(hover: none)").matches){var n=120;t.forEach(function(t){t.addEventListener("mousemove",function(e){var i=t.getBoundingClientRect(),o=i.left+i.width/2,a=i.top+i.height/2,c=e.clientX-o,r=e.clientY-a,d=Math.sqrt(c*c+r*r);if(d<n){var s=(n-d)/n,u=c*s*(25/n),l=r*s*(25/n);t.style.transform="translate("+u+"px, "+l+"px)"}}),t.addEventListener("mouseleave",function(){t.style.transform=""})})}}document.addEventListener("DOMContentLoaded",function(){initMagneticButtons()});